CREATE TABLE "PUBLIC"."TASK_HISTORY" COMMENT 'Timing and metadata info about background/quartz processes'(
    "ID" INTEGER GENERATED BY DEFAULT AS IDENTITY(START WITH 1) NOT NULL,
    "TASK" CHARACTER VARYING(254) COMMENT 'Name of the task' NOT NULL,
    "DB_ID" INTEGER,
    "STARTED_AT" TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "ENDED_AT" TIMESTAMP WITH TIME ZONE DEFAULT NULL,
    "DURATION" INTEGER,
    "TASK_DETAILS" CHARACTER LARGE OBJECT COMMENT 'JSON string with additional info on the task',
    "STATUS" CHARACTER VARYING(21) DEFAULT 'started' COMMENT 'the status of task history, could be started, failed, success, unknown' NOT NULL
);
--;;
