SELECT
    "ID",
    "TASK",
    "STATUS",
    'database_' || "DB_ID" AS "DATABASE_QUALIFIED_ID",
    "STARTED_AT",
    "ENDED_AT",
    CAST("DURATION" AS DOUBLE PRECISION) / 1000 AS "DURATION_SECONDS",
    "TASK_DETAILS" AS "DETAILS"
FROM "PUBLIC"."TASK_HISTORY";
