CREATE FORCE VIEW "PUBLIC"."V_TABLES"("ENTITY_ID", "ENTITY_QUALIFIED_ID", "CREATED_AT", "UPDATED_AT", "NAME", "DISPLAY_NAME", "DESCRIPTION", "ACTIVE", "DATABASE_ID", "SCHEMA", "IS_UPLOAD") AS
SELECT
    "ID" AS "ENTITY_ID",
    'table_' || "ID" AS "ENTITY_QUALIFIED_ID",
    "CREATED_AT",
    "UPDATED_AT",
    "NAME",
    "DISPLAY_NAME",
    "DESCRIPTION",
    "ACTIVE",
    "DB_ID" AS "DATABASE_ID",
    "SCHEMA",
    "IS_UPLOAD"
FROM "PUBLIC"."METABASE_TABLE";
--;;
CREATE TABLE "PUBLIC"."PULSE_CARD"(
    "ID" INTEGER GENERATED BY DEFAULT AS IDENTITY(START WITH 1) NOT NULL,
    "PULSE_ID" INTEGER NOT NULL,
    "CARD_ID" INTEGER NOT NULL,
    "POSITION" INTEGER NOT NULL,
    "INCLUDE_CSV" BOOLEAN DEFAULT FALSE COMMENT 'True if a CSV of the data should be included for this pulse card' NOT NULL,
    "INCLUDE_XLS" BOOLEAN DEFAULT FALSE COMMENT 'True if a XLS of the data should be included for this pulse card' NOT NULL,
    "DASHBOARD_CARD_ID" INTEGER COMMENT 'If this Pulse is a Dashboard subscription, the ID of the DashboardCard that corresponds to this PulseCard.',
    "ENTITY_ID" CHARACTER(21) COMMENT 'Random NanoID tag for unique identity.',
    "FORMAT_ROWS" BOOLEAN DEFAULT 'true' COMMENT 'Whether or not to apply formatting to the rows of the export',
    "PIVOT_RESULTS" BOOLEAN DEFAULT 'false' COMMENT 'Whether or not to apply pivot processing to the rows of the export'
);
--;;
ALTER TABLE "PUBLIC"."PULSE_CARD" ADD CONSTRAINT "PUBLIC"."PK_PULSE_CARD" PRIMARY KEY("ID");
--;;
CREATE INDEX "PUBLIC"."IDX_PULSE_CARD_PULSE_ID" ON "PUBLIC"."PULSE_CARD"("PULSE_ID" NULLS FIRST);
--;;
CREATE INDEX "PUBLIC"."IDX_PULSE_CARD_CARD_ID" ON "PUBLIC"."PULSE_CARD"("CARD_ID" NULLS FIRST);
--;;
CREATE TABLE "PUBLIC"."CONTENT_TRANSLATION" COMMENT 'Content translations'(
    "ID" INTEGER GENERATED BY DEFAULT AS IDENTITY(START WITH 1) COMMENT 'Unique ID' NOT NULL,
    "LOCALE" CHARACTER VARYING(5) COMMENT 'Locale' NOT NULL,
    "MSGID" CHARACTER LARGE OBJECT COMMENT 'The raw string' NOT NULL,
    "MSGSTR" CHARACTER LARGE OBJECT COMMENT 'The translation' NOT NULL
);
--;;
ALTER TABLE "PUBLIC"."CONTENT_TRANSLATION" ADD CONSTRAINT "PUBLIC"."PK_CONTENT_TRANSLATION" PRIMARY KEY("ID");
--;;
CREATE TABLE "PUBLIC"."DOCUMENT" COMMENT 'Documents table'(
    "ID" INTEGER GENERATED BY DEFAULT AS IDENTITY(START WITH 1) COMMENT 'Unique ID' NOT NULL,
    "NAME" CHARACTER LARGE OBJECT COMMENT 'Document name' NOT NULL,
    "CREATED_AT" TIMESTAMP WITH TIME ZONE DEFAULT LOCALTIMESTAMP COMMENT 'The timestamp of when the document was created' NOT NULL,
    "DOCUMENT" CHARACTER LARGE OBJECT COMMENT 'content of the document',
    "CONTENT_TYPE" CHARACTER LARGE OBJECT COMMENT 'the content_type of the document column' NOT NULL,
    "CREATOR_ID" INTEGER COMMENT 'User who created this document' NOT NULL,
    "UPDATED_AT" TIMESTAMP WITH TIME ZONE DEFAULT LOCALTIMESTAMP COMMENT 'The timestamp of when the document was updated' NOT NULL,
    "COLLECTION_ID" INTEGER COMMENT 'What collection I live in. Null if it''s Our Analytics.',
    "ARCHIVED" BOOLEAN DEFAULT FALSE COMMENT 'Has this document been archived?' NOT NULL,
    "ARCHIVED_DIRECTLY" BOOLEAN DEFAULT FALSE COMMENT 'Was this thing trashed directly',
    "ENTITY_ID" CHARACTER(21) COMMENT 'Random NanoID tag for unique identity',
    "LAST_VIEWED_AT" TIMESTAMP WITH TIME ZONE DEFAULT LOCALTIMESTAMP COMMENT 'Timestamp of when this document was last viewed' NOT NULL,
    "VIEW_COUNT" INTEGER DEFAULT 0 COMMENT 'Keeps a running count of document views' NOT NULL,
    "COLLECTION_POSITION" INTEGER COMMENT 'Collection position used for pinning documents. Higher numbers = pinned, null = not pinned.',
    "DEPENDENCY_ANALYSIS_VERSION" SMALLINT DEFAULT '0' COMMENT 'Version of the dependency analysis for this entity.' NOT NULL,
    "PUBLIC_UUID" CHARACTER(36) COMMENT 'UUID for publicly-accessible version of this document',
    "MADE_PUBLIC_BY_ID" INTEGER COMMENT 'ID of the user who made this document public'
);
--;;
