CREATE INDEX "PUBLIC"."IDX_QUERY_TABLE_TABLE_ID" ON "PUBLIC"."QUERY_TABLE"("TABLE_ID" NULLS FIRST);
--;;
CREATE TABLE "PUBLIC"."TRANSFORM_JOB" COMMENT 'Jobs that execute transforms based on tags'(
    "ID" INTEGER GENERATED BY DEFAULT AS IDENTITY(START WITH 1 RESTART WITH 5) COMMENT 'Unique ID' NOT NULL,
    "NAME" CHARACTER LARGE OBJECT COMMENT 'The name of the transform job.' NOT NULL,
    "DESCRIPTION" CHARACTER LARGE OBJECT COMMENT 'A description of the transform job.',
    "SCHEDULE" CHARACTER LARGE OBJECT COMMENT 'Cron expression for job schedule' NOT NULL,
    "ENTITY_ID" CHARACTER(21) COMMENT 'NanoID identifier for the job',
    "CREATED_AT" TIMESTAMP WITH TIME ZONE DEFAULT LOCALTIMESTAMP COMMENT 'The timestamp this transform job was created.' NOT NULL,
    "UPDATED_AT" TIMESTAMP WITH TIME ZONE DEFAULT LOCALTIMESTAMP COMMENT 'The timestamp this transform job was last updated.' NOT NULL,
    "BUILT_IN_TYPE" CHARACTER VARYING(255) COMMENT 'Type of the built-in transform job: hourly, daily, weekly, monthly.',
    "UI_DISPLAY_TYPE" CHARACTER VARYING(32) DEFAULT 'cron/raw' COMMENT 'The display type of the schedule, used for the UI only; "cron/raw" or "cron/builder".' NOT NULL
);
--;;
ALTER TABLE "PUBLIC"."TRANSFORM_JOB" ADD CONSTRAINT "PUBLIC"."PK_TRANSFORM_JOB" PRIMARY KEY("ID");
--;;
