CREATE TABLE "PUBLIC"."REMOTE_SYNC_TASK" COMMENT 'Table to track remote sync tasks and their progress'(
    "ID" INTEGER GENERATED BY DEFAULT AS IDENTITY(START WITH 1) NOT NULL,
    "SYNC_TASK_TYPE" CHARACTER VARYING(24) COMMENT 'Type of the sync task' NOT NULL,
    "PROGRESS" FLOAT COMMENT 'Progress percentage of the sync task (0.0 to 1.0)',
    "CANCELLED" BOOLEAN DEFAULT FALSE COMMENT 'Whether the sync task was cancelled' NOT NULL,
    "STARTED_AT" TIMESTAMP WITH TIME ZONE DEFAULT LOCALTIMESTAMP COMMENT 'Timestamp when the sync task started' NOT NULL,
    "ENDED_AT" TIMESTAMP WITH TIME ZONE COMMENT 'Timestamp when the sync task ended',
    "LAST_PROGRESS_REPORT_AT" TIMESTAMP WITH TIME ZONE DEFAULT LOCALTIMESTAMP COMMENT 'Timestamp of the last progress update' NOT NULL,
    "INITIATED_BY" INTEGER COMMENT 'ID of the user who initiated the sync task',
    "ERROR_MESSAGE" CHARACTER LARGE OBJECT COMMENT 'error message if this task failed',
    "VERSION" CHARACTER VARYING(50) COMMENT 'Version that was imported or exported (ex the Git SHA)'
);
