--;;
CREATE INDEX "PUBLIC"."IDX_QUERY_FIELD_FIELD_ID" ON "PUBLIC"."QUERY_FIELD"("FIELD_ID" NULLS FIRST);
--;;
CREATE TABLE "PUBLIC"."DOCUMENT_BOOKMARK" COMMENT 'Store user bookmarks for documents'(
    "ID" INTEGER GENERATED BY DEFAULT AS IDENTITY(START WITH 1) COMMENT 'Unique ID' NOT NULL,
    "USER_ID" INTEGER COMMENT 'User who bookmarked the document' NOT NULL,
    "DOCUMENT_ID" INTEGER COMMENT 'The document that was bookmarked' NOT NULL,
    "CREATED_AT" TIMESTAMP WITH TIME ZONE DEFAULT LOCALTIMESTAMP COMMENT 'The timestamp when the bookmark was created' NOT NULL
);
--;;
ALTER TABLE "PUBLIC"."DOCUMENT_BOOKMARK" ADD CONSTRAINT "PUBLIC"."PK_DOCUMENT_BOOKMARK" PRIMARY KEY("ID");
--;;
CREATE INDEX "PUBLIC"."IDX_DOCUMENT_BOOKMARK_USER_ID" ON "PUBLIC"."DOCUMENT_BOOKMARK"("USER_ID" NULLS FIRST);
--;;
CREATE INDEX "PUBLIC"."IDX_DOCUMENT_BOOKMARK_DOCUMENT_ID" ON "PUBLIC"."DOCUMENT_BOOKMARK"("DOCUMENT_ID" NULLS FIRST);
--;;
CREATE TABLE "PUBLIC"."SANDBOXES" COMMENT 'Records that a given Card (Question) should automatically replace a given Table as query source for a given a Perms Group.'(
    "ID" INTEGER GENERATED BY DEFAULT AS IDENTITY(START WITH 1) NOT NULL,
    "GROUP_ID" INTEGER COMMENT 'ID of the Permissions Group this policy affects.' NOT NULL,
    "TABLE_ID" INTEGER COMMENT 'ID of the Table that should get automatically replaced as query source for the Permissions Group.' NOT NULL,
    "CARD_ID" INTEGER COMMENT 'ID of the Card (Question) to be used to replace the Table.',
    "ATTRIBUTE_REMAPPINGS" CHARACTER LARGE OBJECT COMMENT 'JSON-encoded map of user attribute identifier to the param name used in the Card.',
    "DEPENDENCY_ANALYSIS_VERSION" SMALLINT DEFAULT '0' COMMENT 'Version of the dependency analysis for this entity.' NOT NULL
);
--;;
ALTER TABLE "PUBLIC"."SANDBOXES" ADD CONSTRAINT "PUBLIC"."PK_GROUP_TABLE_ACCESS_POLICY" PRIMARY KEY("ID");
--;;
CREATE INDEX "PUBLIC"."IDX_GTAP_TABLE_ID_GROUP_ID" ON "PUBLIC"."SANDBOXES"("TABLE_ID" NULLS FIRST, "GROUP_ID" NULLS FIRST);
--;;
CREATE INDEX "PUBLIC"."IDX_SANDBOXES_DEPENDENCY_ANALYSIS_VERSION" ON "PUBLIC"."SANDBOXES"("DEPENDENCY_ANALYSIS_VERSION" NULLS FIRST);
--;;
CREATE TABLE "PUBLIC"."METABOT_MESSAGE" COMMENT 'Table to store metabot conversation messages'(
    "ID" INTEGER GENERATED BY DEFAULT AS IDENTITY(START WITH 1) COMMENT 'Autoincrement PK' NOT NULL,
    "CREATED_AT" TIMESTAMP WITH TIME ZONE DEFAULT LOCALTIMESTAMP COMMENT 'created_at' NOT NULL,
    "PROFILE_ID" CHARACTER LARGE OBJECT COMMENT 'ai-service profile used to perform the conversation' NOT NULL,
    "ROLE" CHARACTER VARYING(20) COMMENT 'Role of the sender' NOT NULL,
    "DATA" CHARACTER LARGE OBJECT COMMENT 'Full message content' NOT NULL,
    "USAGE" CHARACTER LARGE OBJECT COMMENT 'Can be null for user messages; {"<model-name>": {"prompt": 1, "completion": 2}}',
    "TOTAL_TOKENS" INTEGER COMMENT 'A sum of all prompt+completion from `usage`' NOT NULL,
    "CONVERSATION_ID" CHARACTER VARYING(36) COMMENT 'Reference to a conversation' NOT NULL
);
--;;
ALTER TABLE "PUBLIC"."METABOT_MESSAGE" ADD CONSTRAINT "PUBLIC"."PK_METABOT_MESSAGE" PRIMARY KEY("ID");
--;;
CREATE INDEX "PUBLIC"."IDX_METABOT_MESSAGE_CONVERSATION_ID" ON "PUBLIC"."METABOT_MESSAGE"("CONVERSATION_ID" NULLS FIRST);
--;;
CREATE TABLE "PUBLIC"."METABOT" COMMENT 'Metabot configuration'(
    "ID" INTEGER GENERATED BY DEFAULT AS IDENTITY(START WITH 1 RESTART WITH 3) NOT NULL,
    "NAME" CHARACTER VARYING(254) COMMENT 'The name of the metabot' NOT NULL,
    "DESCRIPTION" CHARACTER LARGE OBJECT COMMENT 'Description of the metabot',
    "ENTITY_ID" CHARACTER(21) COMMENT 'Random NanoID tag for unique identity',
    "CREATED_AT" TIMESTAMP WITH TIME ZONE DEFAULT LOCALTIMESTAMP COMMENT 'The timestamp of when the metabot was created' NOT NULL,
    "UPDATED_AT" TIMESTAMP WITH TIME ZONE DEFAULT LOCALTIMESTAMP COMMENT 'The timestamp of when the metabot was updated' NOT NULL,
    "USE_VERIFIED_CONTENT" BOOLEAN DEFAULT FALSE COMMENT 'Whether this metabot should only use verified content',
    "COLLECTION_ID" INTEGER COMMENT 'ID of the collection this metabot can access'
);
--;;
ALTER TABLE "PUBLIC"."METABOT" ADD CONSTRAINT "PUBLIC"."PK_METABOT" PRIMARY KEY("ID");
--;;
