    "STATUS" CHARACTER VARYING(50) COMMENT 'Current status of the transform job (running, completed, failed, etc.)' NOT NULL,
    "IS_ACTIVE" BOOLEAN COMMENT 'True only for currently running jobs, null for the others',
    "START_TIME" TIMESTAMP WITH TIME ZONE DEFAULT LOCALTIMESTAMP COMMENT 'When the transform job started' NOT NULL,
    "END_TIME" TIMESTAMP WITH TIME ZONE COMMENT 'When the transform job completed (null if still running)',
