CREATE TABLE "PUBLIC"."DATA_EDIT_UNDO_CHAIN" COMMENT 'Store the state necessary to power undo / redo.'(
    "ID" INTEGER GENERATED BY DEFAULT AS IDENTITY(START WITH 1) NOT NULL,
    "BATCH_NUM" INTEGER COMMENT 'Batch number for grouped changes (global increment)' NOT NULL,
    "TABLE_ID" INTEGER COMMENT 'Reference to the table being modified' NOT NULL,
    "ROW_PK" CHARACTER LARGE OBJECT COMMENT 'PK of the row being modified, potentially composite. Stored as a sorted JSON map.' NOT NULL,
    "USER_ID" INTEGER COMMENT 'ID of the user who made the change' NOT NULL,
    "SCOPE" CHARACTER LARGE OBJECT COMMENT 'Identifies where the changes were made from' NOT NULL,
    "UNDOABLE" BOOLEAN DEFAULT TRUE COMMENT 'Identifies whether a change can be undo' NOT NULL,
    "RAW_BEFORE" CHARACTER LARGE OBJECT COMMENT 'Value of the field before the change',
    "RAW_AFTER" CHARACTER LARGE OBJECT COMMENT 'Value of the field after the change',
    "UNDONE" BOOLEAN DEFAULT FALSE COMMENT 'Whether this change has been undone' NOT NULL,
    "CREATED_AT" TIMESTAMP WITH TIME ZONE DEFAULT LOCALTIMESTAMP COMMENT 'The timestamp of when the change was created' NOT NULL,
    "UPDATED_AT" TIMESTAMP WITH TIME ZONE DEFAULT LOCALTIMESTAMP COMMENT 'The timestamp of when the change was updated' NOT NULL
);
--;;
ALTER TABLE "PUBLIC"."DATA_EDIT_UNDO_CHAIN" ADD CONSTRAINT "PUBLIC"."PK_DATA_EDIT_UNDO_CHAIN" PRIMARY KEY("ID");
