CREATE TABLE "PUBLIC"."SECURITY_ADVISORY" COMMENT 'Stores security advisories fetched from the advisory feed'(
    "ID" INTEGER GENERATED BY DEFAULT AS IDENTITY(START WITH 1) COMMENT 'Auto-incrementing primary key' NOT NULL,
    "ADVISORY_ID" CHARACTER VARYING(255) COMMENT 'Unique advisory identifier (e.g. SC-2026-001)' NOT NULL,
    "SEVERITY" CHARACTER VARYING(32) COMMENT 'Severity level: critical, high, medium, or low' NOT NULL,
    "TITLE" CHARACTER VARYING(255) COMMENT 'Human-readable advisory title' NOT NULL,
    "DESCRIPTION" CHARACTER LARGE OBJECT COMMENT 'Short summary of the advisory' NOT NULL,
    "ADVISORY_URL" CHARACTER VARYING(2048) COMMENT 'Link to the full advisory',
    "REMEDIATION" CHARACTER LARGE OBJECT COMMENT 'Remediation instructions' NOT NULL,
    "AFFECTED_VERSIONS" CHARACTER LARGE OBJECT COMMENT 'JSON array of {min, fixed} version ranges' NOT NULL,
    "MATCHING_QUERY" CHARACTER LARGE OBJECT COMMENT 'JSON HoneySQL query keyed by dialect (null = affects all instances)',
    "PUBLISHED_AT" TIMESTAMP WITH TIME ZONE COMMENT 'When the advisory was published' NOT NULL,
    "FETCHED_AT" TIMESTAMP WITH TIME ZONE DEFAULT LOCALTIMESTAMP COMMENT 'When Metabase fetched this advisory' NOT NULL,
    "MATCH_STATUS" CHARACTER VARYING(32) COMMENT 'Status: active, resolved, not_affected, or error' NOT NULL,
    "LAST_EVALUATED_AT" TIMESTAMP WITH TIME ZONE COMMENT 'Last time the matching query was evaluated',
    "ACKNOWLEDGED_BY" INTEGER COMMENT U&'FK to core_user.id \2014 admin who acknowledged the advisory',
    "ACKNOWLEDGED_AT" TIMESTAMP WITH TIME ZONE COMMENT 'When the advisory was acknowledged',
    "LAST_NOTIFIED_AT" TIMESTAMP WITH TIME ZONE COMMENT 'When the last notification was sent for this advisory',
    "UPDATED_AT" TIMESTAMP WITH TIME ZONE COMMENT 'When the advisory was last updated upstream (used as sync cursor)' NOT NULL,
    "DOWNLOAD_JAR_URLS" CHARACTER LARGE OBJECT COMMENT 'JSON array of {version, url} downloadable JARs'
);
--;;
