    "TAG_ID" INTEGER COMMENT 'The id of the tag.' NOT NULL,
    "ENTITY_ID" CHARACTER(21) COMMENT 'Random NanoID tag for unique identity.',
    "POSITION" INTEGER COMMENT 'The relative UI ordering of this tag on the transform' NOT NULL
);
--;;
ALTER TABLE "PUBLIC"."TRANSFORM_TRANSFORM_TAG" ADD CONSTRAINT "PUBLIC"."PK_TRANSFORM_TRANSFORM_TAG" PRIMARY KEY("ID");
--;;
CREATE TABLE "PUBLIC"."TRANSFORM_JOB_TRANSFORM_TAG" COMMENT 'Join table for jobs and tags'(
    "ID" INTEGER GENERATED BY DEFAULT AS IDENTITY(START WITH 1 RESTART WITH 5) COMMENT 'Unique ID' NOT NULL,
    "JOB_ID" INTEGER COMMENT 'The id of the transform job.' NOT NULL,
    "TAG_ID" INTEGER COMMENT 'The id of the transform tag.' NOT NULL,
    "ENTITY_ID" CHARACTER(21) COMMENT 'Random NanoID tag for unique identity.',
    "POSITION" INTEGER COMMENT 'The ordering position of this tag for the job.' NOT NULL
);
--;;
ALTER TABLE "PUBLIC"."TRANSFORM_JOB_TRANSFORM_TAG" ADD CONSTRAINT "PUBLIC"."PK_TRANSFORM_JOB_TRANSFORM_TAG" PRIMARY KEY("ID");
--;;
