CREATE TABLE "PUBLIC"."TRANSFORM_JOB_RUN" COMMENT 'Table to track transform job executions and their status in the app database'(
    "ID" INTEGER GENERATED BY DEFAULT AS IDENTITY(START WITH 1) COMMENT 'Unique ID' NOT NULL,
    "JOB_ID" BIGINT COMMENT 'Identifier for the transform job' NOT NULL,
    "RUN_METHOD" CHARACTER VARYING(255) COMMENT 'Method used to execute the transform job' NOT NULL,
    "STATUS" CHARACTER VARYING(50) COMMENT 'Current status of the transform job (running, completed, failed, etc.)' NOT NULL,
    "IS_ACTIVE" BOOLEAN COMMENT 'True only for currently running jobs, null for the others',
    "START_TIME" TIMESTAMP WITH TIME ZONE DEFAULT LOCALTIMESTAMP COMMENT 'When the transform job started' NOT NULL,
    "END_TIME" TIMESTAMP WITH TIME ZONE COMMENT 'When the tranform job completed (null if still running)',
    "MESSAGE" CHARACTER LARGE OBJECT COMMENT 'Human-readable message about the run; may contain error message in case status is error',
    "CREATED_AT" TIMESTAMP WITH TIME ZONE DEFAULT LOCALTIMESTAMP COMMENT 'The timestamp this transform job run was created.' NOT NULL,
    "UPDATED_AT" TIMESTAMP WITH TIME ZONE DEFAULT LOCALTIMESTAMP COMMENT 'The timestamp this transform job run was last updated.' NOT NULL
);
--;;
ALTER TABLE "PUBLIC"."TRANSFORM_JOB_RUN" ADD CONSTRAINT "PUBLIC"."PK_TRANSFORM_JOB_RUN" PRIMARY KEY("ID");
--;;
CREATE TABLE "PUBLIC"."PYTHON_LIBRARY" COMMENT 'Store Python library code for user modules in transforms'(
    "ID" INTEGER GENERATED BY DEFAULT AS IDENTITY(START WITH 1) COMMENT 'Primary key for python_library' NOT NULL,
    "PATH" CHARACTER VARYING(254) COMMENT 'Path identifier for the library' NOT NULL,
    "SOURCE" CHARACTER LARGE OBJECT COMMENT 'Python source code for user modules',
    "CREATED_AT" TIMESTAMP WITH TIME ZONE DEFAULT LOCALTIMESTAMP COMMENT 'When the record was created' NOT NULL,
    "UPDATED_AT" TIMESTAMP WITH TIME ZONE DEFAULT LOCALTIMESTAMP COMMENT 'When the record was last updated' NOT NULL
);
--;;
ALTER TABLE "PUBLIC"."PYTHON_LIBRARY" ADD CONSTRAINT "PUBLIC"."PK_PYTHON_LIBRARY" PRIMARY KEY("ID");
--;;
CREATE TABLE "PUBLIC"."REMOTE_SYNC_OBJECT" COMMENT 'Track remote sync objects'(
    "ID" INTEGER GENERATED BY DEFAULT AS IDENTITY(START WITH 1) COMMENT 'Primary key identifier for remote-sync objects' NOT NULL,
    "MODEL_TYPE" CHARACTER VARYING(32) COMMENT 'Type of model' NOT NULL,
    "MODEL_ID" INTEGER COMMENT 'ID of the model' NOT NULL,
    "STATUS" CHARACTER VARYING(32) COMMENT 'Status of the object' NOT NULL,
    "STATUS_CHANGED_AT" TIMESTAMP WITH TIME ZONE COMMENT 'When the status changed' NOT NULL,
    "MODEL_NAME" CHARACTER VARYING(255) COMMENT 'Copy of the name from the object being sync''ed' NOT NULL,
    "MODEL_COLLECTION_ID" INTEGER COMMENT 'Copy of the collection from the object being sync''ed',
    "MODEL_DISPLAY" CHARACTER VARYING(50) COMMENT 'Copy of the display field from the object being sync''ed'
);
--;;
ALTER TABLE "PUBLIC"."REMOTE_SYNC_OBJECT" ADD CONSTRAINT "PUBLIC"."PK_REMOTE_SYNC_OBJECT" PRIMARY KEY("ID");
--;;
CREATE INDEX "PUBLIC"."IDX_REMOTE_SYNC_OBJECT_MODEL_LOOKUP" ON "PUBLIC"."REMOTE_SYNC_OBJECT"("MODEL_TYPE" NULLS FIRST, "MODEL_ID" NULLS FIRST);
--;;
CREATE TABLE "PUBLIC"."COMMENT" COMMENT 'Comments on various entities (documents, dashboards, etc.)'(
    "ID" INTEGER GENERATED BY DEFAULT AS IDENTITY(START WITH 1) COMMENT 'Primary key for comment table' NOT NULL,
    "PARENT_COMMENT_ID" INTEGER COMMENT 'ID of the parent comment for threading (null for root comments)',
    "TARGET_TYPE" CHARACTER VARYING(50) DEFAULT 'document' COMMENT 'Type of entity being commented on' NOT NULL,
    "TARGET_ID" INTEGER COMMENT 'ID of the entity being commented on' NOT NULL,
    "CHILD_TARGET_ID" CHARACTER LARGE OBJECT COMMENT 'Sub-entity ID (e.g., document block node ID)',
    "CREATOR_ID" INTEGER COMMENT 'User who created this comment' NOT NULL,
    "CONTENT" CHARACTER LARGE OBJECT COMMENT 'The comment content' NOT NULL,
    "IS_RESOLVED" BOOLEAN DEFAULT FALSE COMMENT 'Whether this comment thread is resolved' NOT NULL,
    "CREATED_AT" TIMESTAMP WITH TIME ZONE DEFAULT LOCALTIMESTAMP COMMENT 'Timestamp when comment was created' NOT NULL,
    "UPDATED_AT" TIMESTAMP WITH TIME ZONE DEFAULT LOCALTIMESTAMP COMMENT 'Timestamp when comment was last updated' NOT NULL,
    "DELETED_AT" TIMESTAMP WITH TIME ZONE COMMENT 'Soft delete timestamp (null if not deleted)',
    "CONTENT_HTML" CHARACTER LARGE OBJECT COMMENT 'HTML-rendered version of the comment content'
);
--;;
ALTER TABLE "PUBLIC"."COMMENT" ADD CONSTRAINT "PUBLIC"."PK_COMMENT" PRIMARY KEY("ID");
--;;
CREATE INDEX "PUBLIC"."IDX_COMMENT_ENTITY" ON "PUBLIC"."COMMENT"("TARGET_TYPE" NULLS FIRST, "TARGET_ID" NULLS FIRST);
--;;
